import{_ as a,o as t,c as s,ag as o}from"./chunks/framework.2cFhd8Ux.js";const u=JSON.parse('{"title":"Agent Safety Contract","description":"","frontmatter":{"source":"setup/safety-contract.md"},"headers":[],"relativePath":"setup/safety-contract.md","filePath":"setup/safety-contract.md"}'),r={name:"setup/safety-contract.md"};function n(i,e,c,d,l,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="agent-safety-contract" tabindex="-1">Agent Safety Contract <a class="header-anchor" href="#agent-safety-contract" aria-label="Permalink to &quot;Agent Safety Contract&quot;">​</a></h1><blockquote><p>Read it in week 0. Sign it on Canvas in week 1. It is personal, so don&#39;t commit it to a repository.</p></blockquote><p>This contract is adapted from the sibling course&#39;s nine-rule safety contract (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/setup/safety-contract.html" target="_blank" rel="noreferrer">Building Apps with AI</a>), rewritten for agents that run on large codebases you didn&#39;t write, with MCP servers, CI and other people&#39;s repositories in reach. Each rule has a short version, the week the course teaches it, and the incident or study behind it. The incidents are in <a href="./../resources/case-studies.html">Case Studies</a>.</p><p><strong>Why a contract, not just advice.</strong> An <code>AGENTS.md</code> line that says &quot;never delete the database&quot; is advice the agent may ignore; in two well-known incidents agents deleted production data despite explicit instructions (<a href="./../resources/case-studies.html#c1-replit-the-code-freeze-that-was-only-words">Replit</a>; <a href="./../resources/case-studies.html#c2-pocketos-a-token-found-in-an-unrelated-file">PocketOS</a>). What holds is the setup around the agent: approvals, sandboxes, scoped tokens, empty wallets. These rules are about that setup, and they are yours to keep, because the agent can&#39;t.</p><p><strong>How the course backs you up.</strong> Labs run in Codespaces; the kits are built with an approval gate, a workspace guard and a step limit; the injection lab uses a worthless canary instead of a real key; graded work stays in a class fork, not in maintainers&#39; repositories. If you break a rule by accident, say by committing a key, tell your instructor the same day. Reporting quickly is always the right call, and the fix is usually small.</p><h2 id="the-eleven-rules" tabindex="-1">The eleven rules <a class="header-anchor" href="#the-eleven-rules" aria-label="Permalink to &quot;The eleven rules&quot;">​</a></h2><h3 id="1-the-data-rule" tabindex="-1">1. The data rule <a class="header-anchor" href="#1-the-data-rule" aria-label="Permalink to &quot;1. The data rule&quot;">​</a></h3><p><strong>Short version:</strong> free tiers may train on your prompts, so they see only public open-source code and course kits. <em>Week 0 and week 1.</em></p><p>I send free-tier AI services only public open-source code, the course kits and my own course work. Never personal data, grades or feedback, classmates&#39; writing, secrets, unreleased research code, an employer&#39;s code, or code I don&#39;t have the right to share. I turn off training wherever a setting exists (<a href="./accounts.html#privacy-settings">accounts</a>).</p><p><em>Why: the Gemini API&#39;s free tier is &quot;used to improve our products&quot; with human review and no opt-out, and Copilot&#39;s individual plans train on interaction data unless you opt out (<a href="./../TOOLS.html#the-data-rule">Tool Handout: The data rule</a>).</em></p><h3 id="2-approvals-stay-on" tabindex="-1">2. Approvals stay on <a class="header-anchor" href="#2-approvals-stay-on" aria-label="Permalink to &quot;2. Approvals stay on&quot;">​</a></h3><p><strong>Short version:</strong> the agent asks before every command and every write, unless I allowlisted that exact command. <em>Week 1 (you read the kit&#39;s approval gate, and may extend its approval policy).</em></p><p>I never use autopilot, &quot;yolo&quot;, auto-approve or skip-permissions modes, except where a lab explicitly says to, inside a throwaway sandbox with no secrets attached. Allowlists contain only read-only commands I named (<code>ls</code>, <code>git status</code>, <code>git diff</code>), never a shell, an interpreter or a package manager&#39;s install command; I remember that a test command runs whatever the tests contain. An agent may not edit its own permission settings: I review any change to an agent&#39;s config files as carefully as a change to its code.</p><p><em>Why: injected text made Copilot set its own auto-approve flag, switching off the very prompts meant to stop it (<a href="./../resources/case-studies.html#a4-copilot-edits-its-own-permissions-and-camoleak">CVE-2025-53773</a>). In autopilot mode, a web page sent a project&#39;s secrets to an attacker in about 28 seconds, and the vendor said the user had chosen full autonomy (<a href="./../resources/case-studies.html#a7-autopilot-a-web-page-that-sent-secrets-away">case A7</a>). Anthropic reports that sandboxing cut permission prompts by 84%, which is how to fight approval fatigue: fewer, better prompts, not none (<a href="https://www.anthropic.com/engineering/claude-code-sandboxing" target="_blank" rel="noreferrer">Anthropic</a>).</em></p><h3 id="3-untrusted-code-runs-in-a-sandbox" tabindex="-1">3. Untrusted code runs in a sandbox <a class="header-anchor" href="#3-untrusted-code-runs-in-a-sandbox" aria-label="Permalink to &quot;3. Untrusted code runs in a sandbox&quot;">​</a></h3><p><strong>Short version:</strong> a repository I didn&#39;t write is opened only in a Codespace or a dev container, cloned from its URL. <em>Week 2 (the class codebase) and week 4.</em></p><p>The class codebase, other teams&#39; forks, upstream projects and the injection lab run only in a sandbox (<a href="./sandboxes.html">sandboxes</a>). I clone from the URL; I never open a received folder with an agent. I read a repository&#39;s agent instructions, MCP configs and dev container config before an agent or a build uses them.</p><p><em>Why: a received folder can carry git settings that run an attacker&#39;s program before any approval prompt appears (<a href="./../resources/case-studies.html#a6-received-folders-code-that-runs-before-the-prompt">case A6</a>). Planted instructions in project files made agentic editors run malicious commands up to 84% of the time (<a href="./../resources/case-studies.html#a5-your-ai-my-shell-injection-rates-in-agentic-editors">Liu et al.</a>).</em></p><h3 id="4-no-real-secrets-near-an-agent" tabindex="-1">4. No real secrets near an agent <a class="header-anchor" href="#4-no-real-secrets-near-an-agent" aria-label="Permalink to &quot;4. No real secrets near an agent&quot;">​</a></h3><p><strong>Short version:</strong> an agent session that reads untrusted text has nothing worth stealing in reach. <em>Week 1 (keys) and week 4 (the canary).</em></p><p>My keys are free-tier, with no payment method, kept in <code>.env</code> or a Codespaces secret, never in a repository (<a href="./api-keys.html">api-keys</a>). A sandbox in which an agent reads issues, web pages, PRs, the class codebase or another team&#39;s code has <strong>no</strong> secrets attached beyond the agent&#39;s own free-tier model key, which is worth nothing to steal. No agent ever sees a production credential, my SSH key, a cloud console login, or a classic personal access token.</p><p><em>Why: an agent holding a database service key read instructions in a support ticket and copied secrets into a reply the attacker could see; Willison&#39;s &quot;lethal trifecta&quot; (private data, untrusted content, a way out) explains why (<a href="./../resources/case-studies.html#a1-supabase-mcp-the-lethal-trifecta-in-one-server">case A1</a>). Malware now hunts specifically for AI keys and agent configs (<a href="./../resources/case-studies.html#b4-malware-that-hunts-for-ai-keys">case B4</a>).</em></p><h3 id="5-scoped-tokens-only" tabindex="-1">5. Scoped tokens only <a class="header-anchor" href="#5-scoped-tokens-only" aria-label="Permalink to &quot;5. Scoped tokens only&quot;">​</a></h3><p><strong>Short version:</strong> every token does one job, in one repository, with the fewest permissions, and expires. <em>Week 4; again in week 13 (cloud agents).</em></p><p>I use fine-grained tokens limited to one repository, read-only unless a task needs a write, with an expiry date, named for their job (<a href="./api-keys.html#scoped-tokens">how</a>). CI workflows get <code>contents: read</code> unless a job needs more. MCP servers that reach GitHub get a read-only token where the task allows.</p><p><em>Why: a malicious public issue led an agent with a broad GitHub token to copy private-repository data into a public pull request (<a href="./../resources/case-studies.html#a2-github-mcp-a-public-issue-leaks-a-private-repository">case A2</a>). An agent deleted production data with a token it found in an unrelated file, made for a different job (<a href="./../resources/case-studies.html#c2-pocketos-a-token-found-in-an-unrelated-file">case C2</a>).</em></p><h3 id="6-spending-caps-at-zero" tabindex="-1">6. Spending caps at zero <a class="header-anchor" href="#6-spending-caps-at-zero" aria-label="Permalink to &quot;6. Spending caps at zero&quot;">​</a></h3><p><strong>Short version:</strong> nothing in the course can spend money; anything metered has its cap at zero or the lowest value allowed. <em>Week 0; week 9 (CI) and week 13 (agentic workflows).</em></p><p>No payment method on any course account. No paid budget on Copilot. I never run an agentic workflow or cloud agent whose per-run cap could exceed a free allowance: I lower the cap before the first run. Department-funded credits, if any, have a hard limit and no automatic top-up.</p><p><em>Why: GitHub Agentic Workflows&#39; default per-run cap is several times a student&#39;s monthly Copilot allowance (<a href="./../TOOLS.html#free-infrastructure">Tool Handout: Free infrastructure</a>). Stolen AI keys have run up charges of more than $1,000 (<a href="./../resources/case-studies.html#b4-malware-that-hunts-for-ai-keys">case B4</a>). An empty wallet is the only cap that can&#39;t be misconfigured.</em></p><h3 id="7-save-points-before-and-after" tabindex="-1">7. Save points before and after <a class="header-anchor" href="#7-save-points-before-and-after" aria-label="Permalink to &quot;7. Save points before and after&quot;">​</a></h3><p><strong>Short version:</strong> commit before an agent starts and after it finishes, on a branch or worktree; backups live where the agent can&#39;t reach them. <em>Week 1; worktrees in week 13.</em></p><p>Every agent task starts from a clean commit on its own branch (or git worktree) and ends with a commit I&#39;ve read. Agents never run <code>git push --force</code>, <code>git reset --hard</code> or history rewrites without my approval. <code>main</code> in the team fork is protected; my pushed history is my backup.</p><p><em>Why: an agent&#39;s undo is not a backup. In the PocketOS incident the backups sat on the same volume the agent deleted (<a href="./../resources/case-studies.html#c2-pocketos-a-token-found-in-an-unrelated-file">case C2</a>).</em></p><h3 id="8-read-before-you-adopt" tabindex="-1">8. Read before you adopt <a class="header-anchor" href="#8-read-before-you-adopt" aria-label="Permalink to &quot;8. Read before you adopt&quot;">​</a></h3><p><strong>Short version:</strong> an MCP server, skill, rules file, <code>AGENTS.md</code>, GitHub Action, dev container or package is someone else&#39;s code until I&#39;ve read it. <em>Week 3 (MCP and <code>AGENTS.md</code>) and week 10 (supply chain).</em></p><p>I install only what my plan named. I check that a package exists, is the one I meant and is maintained, and I pin its version. I read every MCP server&#39;s tool descriptions, every skill and every rules file before an agent loads it, and I pin Actions to a version I&#39;ve read.</p><p><em>Why: MCP tool descriptions can carry hidden instructions the user never sees, and a server can change its descriptions after approval (<a href="./../resources/case-studies.html#a3-mcp-tool-poisoning-instructions-the-user-never-sees">case A3</a>). Models invent package names that attackers then register (<a href="./../resources/case-studies.html#b5-slopsquatting-packages-that-dont-exist">case B5</a>), and real, popular packages get hijacked too (<a href="./../resources/case-studies.html#b1-shai-hulud-a-self-replicating-npm-worm">case B1</a>).</em></p><h3 id="9-verify-and-say-how" tabindex="-1">9. Verify, and say how <a class="header-anchor" href="#9-verify-and-say-how" aria-label="Permalink to &quot;9. Verify, and say how&quot;">​</a></h3><p><strong>Short version:</strong> every claim about code, an agent or a tool is tagged <strong>observed</strong> (I ran or read it) or <strong>inferred</strong> (I or the AI concluded it), and only observed claims count as verified. <em>Week 1 (trace dissection); tests in weeks 6–7.</em></p><p>I run the tests myself and read the output. I check that an agent didn&#39;t weaken, skip or delete a test to make it pass. I don&#39;t merge what I can&#39;t explain.</p><p><em>Why: tests written after the code tend to agree with its bugs (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>); LLM-generated oracles capture what code does, not what it should do (<a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">Konstantinou, Degiovanni &amp; Papadakis</a>); and about half of functionally correct backends generated by the best model in one benchmark were exploitable (<a href="https://arxiv.org/abs/2502.11844" target="_blank" rel="noreferrer">BaxBench</a>).</em></p><h3 id="10-no-unattended-agents-in-other-peoples-spaces" tabindex="-1">10. No unattended agents in other people&#39;s spaces <a class="header-anchor" href="#10-no-unattended-agents-in-other-peoples-spaces" aria-label="Permalink to &quot;10. No unattended agents in other people&#39;s spaces&quot;">​</a></h3><p><strong>Short version:</strong> no agent posts, comments, opens or reviews anything in a repository I don&#39;t own without me reading it first; I write my own PR descriptions. <em>Week 9 (the PR round); weeks 12–15 (optional upstream PRs).</em></p><p>No agent publishes anything (a repository, gist, release, issue, comment or PR) without my approval. In other teams&#39; forks and upstream projects, every word posted under my name is one I wrote or read and approved; PR descriptions and review comments I sign are my own writing (🔴 AI off). Upstream, I follow the project&#39;s own AI policy when it is stricter than the course&#39;s, keep one open PR per project, and can explain every line.</p><p><em>Why: agents asked for screenshots created public repositories and published more than 13,000 internal images, with no attacker involved (<a href="./../resources/case-studies.html#a8-pixelleak-helpful-agents-publish-13000-screenshots">case A8</a>). LLVM bans agents that act &quot;without human approval&quot; and asks for self-written PR descriptions (<a href="./../resources/case-studies.html#e3-llvm-a-human-in-the-loop-and-an-assisted-by-trailer">case E3</a>); maintainers have closed their bug bounty and throttled PRs because of AI-generated noise (<a href="./../resources/case-studies.html#e6-curl-ends-its-bug-bounty">cases E6–E7</a>).</em></p><h3 id="11-disclose-ai-help" tabindex="-1">11. Disclose AI help <a class="header-anchor" href="#11-disclose-ai-help" aria-label="Permalink to &quot;11. Disclose AI help&quot;">​</a></h3><p><strong>Short version:</strong> <code>AI_LOG.md</code> in every repository, an <code>Assisted-by:</code> trailer on AI-assisted commits, and the PR template&#39;s AI section filled in honestly. <em>Week 1.</em></p><p>My <code>AI_LOG.md</code> records each significant session: tool and model, what I delegated, what I verified and how (<a href="./../templates/AI_LOG.html">template</a>). AI-assisted commits end with <code>Assisted-by: [tool and model]</code>. I never let an agent add a sign-off or attribution on my behalf.</p><p><em>Why: detectors that try to spot agent-written commits reach a precision of only 0.332 at realistic prevalence, so &quot;detection cannot replace recorded attribution&quot; (<a href="https://arxiv.org/abs/2610.36229" target="_blank" rel="noreferrer">Horikawa et al.</a>). The Linux kernel&#39;s rule is blunt: &quot;AI agents MUST NOT add Signed-off-by tags&quot; (<a href="./../resources/case-studies.html#e4-the-linux-kernel-drops-its-ai-tag">case E4</a>).</em></p><h2 id="and-three-project-rules" tabindex="-1">And three project rules <a class="header-anchor" href="#and-three-project-rules" aria-label="Permalink to &quot;And three project rules&quot;">​</a></h2><ul><li><strong>No real personal data.</strong> Test data is made up. The class codebase and kits contain none.</li><li><strong>No human-subjects research without IRB approval.</strong> Graduate studies use public datasets or your own artifacts, never classmates or maintainers as subjects (<a href="./../resources/case-studies.html#e8-hypocrite-commits-when-research-gets-an-institution-banned">case E8</a>; <a href="./../templates/STUDY_PROTOCOL.html">template</a>).</li><li><strong>Nothing you&#39;d miss if an agent deleted it.</strong> Real documents stay out of agent workspaces.</li></ul><h2 id="signature" tabindex="-1">Signature <a class="header-anchor" href="#signature" aria-label="Permalink to &quot;Signature&quot;">​</a></h2><p>On Canvas, in week 1: open the safety contract assignment and type the statement below with your name and the date.</p><blockquote><p>I have read the agent safety contract and will follow it in this course, from the week each rule is taught. If I&#39;m unsure whether something is safe, I will ask before I do it. If I break a rule by accident, I will tell my instructor the same day.</p></blockquote><p>Back to <a href="./">Week 0</a></p>',56)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
